\draw[->] (0,-0.6) -- (0,4.4) node[above] {$y$};
\draw[thick, <->, domain=-0.6:2, samples=60, variable=\x] plot ({\x},{\x*\x});
\draw[thick, <->, domain=1:4, samples=60, variable=\x] plot ({\x},{(\x-3)*(\x-3)});
\node[font=\small] at (0.68,2.0) {$y=x^{2}$};
\node[font=\small] at (3.9,3.0) {$y=(x-3)^{2}$};
\node[below] at (3,-0.15) {$3$};
\end{tikzpicture}[/tikz]
